"""Load application settings from a JSON file, falling back to built-in defaults."""

import json
import logging
from pathlib import Path

logger = logging.getLogger(__name__)

MIN_PORT = 1024
MAX_PORT = 65535

DEFAULT_SETTINGS = {
    "host": "127.0.0.1",
    "port": 8080,
    "log_level": "INFO",
    "max_connections": 100,
    "request_timeout_seconds": 30,
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be parsed or validated."""


def _check_port(value):
    """Return None if `value` is a usable port, else a message explaining why not."""
    if isinstance(value, bool) or not isinstance(value, int):
        return f"port must be an integer, got {type(value).__name__}"
    if not MIN_PORT <= value <= MAX_PORT:
        return f"port must be between {MIN_PORT} and {MAX_PORT}, got {value}"
    return None


def load_config(path, strict=False):
    """Return settings from the JSON file at `path`, merged over the defaults.

    A missing file yields the defaults. A malformed file, a non-object file, or
    an out-of-range `port` yields the defaults too, unless `strict` is set, in
    which case ConfigError is raised.
    """
    path = Path(path)
    settings = dict(DEFAULT_SETTINGS)

    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        logger.info("No config at %s; using defaults", path)
        return settings
    except OSError as exc:
        if strict:
            raise ConfigError(f"cannot read {path}: {exc}") from exc
        logger.warning("Cannot read %s (%s); using defaults", path, exc)
        return settings

    try:
        loaded = json.loads(raw)
    except json.JSONDecodeError as exc:
        if strict:
            raise ConfigError(f"invalid JSON in {path}: {exc}") from exc
        logger.warning("Invalid JSON in %s (%s); using defaults", path, exc)
        return settings

    if not isinstance(loaded, dict):
        if strict:
            raise ConfigError(f"{path} must contain a JSON object")
        logger.warning("%s is not a JSON object; using defaults", path)
        return settings

    unknown = set(loaded) - set(DEFAULT_SETTINGS)
    if unknown:
        logger.warning("Ignoring unknown keys in %s: %s", path, ", ".join(sorted(unknown)))

    if "port" in loaded:
        problem = _check_port(loaded["port"])
        if problem:
            if strict:
                raise ConfigError(f"{path}: {problem}")
            logger.warning("%s: %s; using port %d", path, problem, settings["port"])
            loaded = {key: value for key, value in loaded.items() if key != "port"}

    settings.update({key: value for key, value in loaded.items() if key in DEFAULT_SETTINGS})
    return settings
